//! Built-in recording list: the structure of the "Kurosu 8-mora" continuous list, generated by
//! its published rule. One section per consonant row; in a section the vowel pattern
//! `[0, 0, N, 1, 0, 2, 0, 1]` is shifted by 0..4 over five lines, so that every (previous vowel,
//! mora) pair, the head position and the moraic nasal appear in some line. Because the
//! physical model does not have to be recorded, this list stands for the whole inventory.

/// Rows of the inventory: (name of the section, kana for the vowels a i u e o).
const ROWS: [(&str, [&str; 5]); 29] = [
    ("?", ["あ", "い", "う", "え", "お"]),
    ("k", ["か", "き", "く", "け", "こ"]),
    ("s", ["さ", "すぃ", "す", "せ", "そ"]),
    ("t", ["た", "てぃ", "とぅ", "て", "と"]),
    ("n", ["な", "に", "ぬ", "ね", "の"]),
    ("h", ["は", "ひ", "ふ", "へ", "ほ"]),
    ("m", ["ま", "み", "む", "め", "も"]),
    ("y", ["や", "い", "ゆ", "いぇ", "よ"]),
    ("r", ["ら", "り", "る", "れ", "ろ"]),
    ("w", ["わ", "うぃ", "う", "うぇ", "うぉ"]),
    ("g", ["が", "ぎ", "ぐ", "げ", "ご"]),
    ("z", ["ざ", "ずぃ", "ず", "ぜ", "ぞ"]),
    ("d", ["だ", "でぃ", "どぅ", "で", "ど"]),
    ("b", ["ば", "び", "ぶ", "べ", "ぼ"]),
    ("p", ["ぱ", "ぴ", "ぷ", "ぺ", "ぽ"]),
    ("K", ["きゃ", "き", "きゅ", "きぇ", "きょ"]),
    ("S", ["しゃ", "し", "しゅ", "しぇ", "しょ"]),
    ("C", ["ちゃ", "ち", "ちゅ", "ちぇ", "ちょ"]),
    ("T", ["つぁ", "つぃ", "つ", "つぇ", "つぉ"]),
    ("N", ["にゃ", "に", "にゅ", "にぇ", "にょ"]),
    ("H", ["ひゃ", "ひ", "ひゅ", "ひぇ", "ひょ"]),
    ("F", ["ふぁ", "ふぃ", "ふ", "ふぇ", "ふぉ"]),
    ("M", ["みゃ", "み", "みゅ", "みぇ", "みょ"]),
    ("R", ["りゃ", "り", "りゅ", "りぇ", "りょ"]),
    ("G", ["ぎゃ", "ぎ", "ぎゅ", "ぎぇ", "ぎょ"]),
    ("J", ["じゃ", "じ", "じゅ", "じぇ", "じょ"]),
    ("B", ["びゃ", "び", "びゅ", "びぇ", "びょ"]),
    ("P", ["ぴゃ", "ぴ", "ぴゅ", "ぴぇ", "ぴょ"]),
    ("V", ["ヴぁ", "ヴぃ", "ヴ", "ヴぇ", "ヴぉ"]),
];

/// Vowel indices of the eight morae of a line (`None`: the moraic nasal).
const PATTERN: [Option<usize>; 8] = [Some(0), Some(0), None, Some(1), Some(0), Some(2), Some(0), Some(1)];

/// The list text: 29 sections of five lines, each line starting with `_` (after a pause).
/// A comment line names every section.
pub fn kurosu8_list() -> String {
    let mut out = String::new();
    for (name, kana) in ROWS {
        out.push_str(&format!("# {name}\n"));
        for shift in 0..5 {
            out.push('_');
            for p in PATTERN {
                match p { None => out.push('ん'), Some(v) => out.push_str(kana[(v + shift) % 5]) }
            }
            out.push('\n');
        }
    }
    out
}
